<span class="line"><span style="color:#C678DD;">WITH</span><span style="color:#C678DD;"> IDENTITY</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;mystorageaccount&#39;</span><span style="color:#ABB2BF;">,</span></span>
